CREATE TABLE hb_focus.native_snapshot(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,snapshot_digest text NOT NULL CHECK(snapshot_digest ~ '^[a-f0-9]{64}$'),body jsonb NOT NULL,PRIMARY KEY(tenant_id,batch_id,snapshot_digest),FOREIGN KEY(tenant_id,batch_id) REFERENCES hb_focus.slice);
CREATE TABLE hb_focus.native_node(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,snapshot_digest text NOT NULL,node_id uuid NOT NULL,provider text NOT NULL,partition text NOT NULL,namespace text NOT NULL,kind text NOT NULL,native_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(tenant_id,batch_id,snapshot_digest,node_id),UNIQUE(tenant_id,batch_id,snapshot_digest,provider,partition,namespace,kind,native_id),FOREIGN KEY(tenant_id,batch_id,snapshot_digest) REFERENCES hb_focus.native_snapshot,CHECK(data->>'id'=node_id::text AND data->>'provider'=provider AND data->>'kind'=kind AND data->>'native_id'=native_id));
CREATE TABLE hb_focus.native_edge(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,snapshot_digest text NOT NULL,edge_id text NOT NULL,child uuid NOT NULL,parent uuid NOT NULL,relation text NOT NULL,axis text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(tenant_id,batch_id,snapshot_digest,edge_id),FOREIGN KEY(tenant_id,batch_id,snapshot_digest,child) REFERENCES hb_focus.native_node,FOREIGN KEY(tenant_id,batch_id,snapshot_digest,parent) REFERENCES hb_focus.native_node,CHECK(child<>parent),CHECK(data->>'id'=edge_id AND data->>'child'=child::text AND data->>'parent'=parent::text));
CREATE TABLE hb_focus.native_binding(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,snapshot_digest text NOT NULL,ordinal bigint NOT NULL CHECK(ordinal>0),focus_billing uuid NOT NULL,focus_usage uuid NOT NULL,context jsonb NOT NULL,PRIMARY KEY(tenant_id,batch_id,snapshot_digest,ordinal),FOREIGN KEY(tenant_id,batch_id,snapshot_digest,focus_billing) REFERENCES hb_focus.native_node,FOREIGN KEY(tenant_id,batch_id,snapshot_digest,focus_usage) REFERENCES hb_focus.native_node);
CREATE TABLE hb_focus.native_binding_role(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,snapshot_digest text NOT NULL,ordinal bigint NOT NULL,role text NOT NULL CHECK(role IN ('billing','usage','resource','identity')),node_id uuid NOT NULL,PRIMARY KEY(tenant_id,batch_id,snapshot_digest,ordinal,role),FOREIGN KEY(tenant_id,batch_id,snapshot_digest,ordinal) REFERENCES hb_focus.native_binding,FOREIGN KEY(tenant_id,batch_id,snapshot_digest,node_id) REFERENCES hb_focus.native_node);
CREATE TABLE hb_focus.native_head(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,snapshot_digest text NOT NULL,PRIMARY KEY(tenant_id,batch_id),FOREIGN KEY(tenant_id,batch_id,snapshot_digest) REFERENCES hb_focus.native_snapshot);
CREATE TRIGGER immutable_native_snapshot BEFORE UPDATE OR DELETE ON hb_focus.native_snapshot FOR EACH ROW EXECUTE FUNCTION hb_focus.immutable();
CREATE TRIGGER immutable_native_node BEFORE UPDATE OR DELETE ON hb_focus.native_node FOR EACH ROW EXECUTE FUNCTION hb_focus.immutable();
CREATE TRIGGER immutable_native_edge BEFORE UPDATE OR DELETE ON hb_focus.native_edge FOR EACH ROW EXECUTE FUNCTION hb_focus.immutable();
CREATE TRIGGER immutable_native_binding BEFORE UPDATE OR DELETE ON hb_focus.native_binding FOR EACH ROW EXECUTE FUNCTION hb_focus.immutable();
CREATE TRIGGER immutable_native_binding_role BEFORE UPDATE OR DELETE ON hb_focus.native_binding_role FOR EACH ROW EXECUTE FUNCTION hb_focus.immutable();
